WITH matched_keys AS (SELECT segment, id FROM customers INTERSECT ALL SELECT segment, id FROM customers WHERE credit_limit <= 5100), reconciled AS (SELECT s.* FROM customers s JOIN matched_keys k ON s.segment = k.segment AND s.id = k.id) SELECT DATE_TRUNC('WEEK', signup_date) AS week_start, CASE WHEN age >= 71 THEN 'LARGE' ELSE 'SMALL' END AS age_tier, SIZE(COLLECT_SET(city)) AS num_cities, COUNT(*) AS num_rows, GROUPING(DATE_TRUNC('WEEK', signup_date)) AS gid FROM reconciled GROUP BY CUBE (DATE_TRUNC('WEEK', signup_date), CASE WHEN age >= 71 THEN 'LARGE' ELSE 'SMALL' END) ORDER BY num_rows DESC;
